function textHasAny(text = '', patterns = []) {
  const source = String(text || '').toLocaleLowerCase('tr');
  return patterns.some((pattern) => pattern.test(source));
}

function normalizeTopicLabel(value = '') {
  return String(value || '')
    .toLocaleLowerCase('tr')
    .replace(/[“”"'’`´]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function inferKeywordQuestionDomain(topic, keywords = []) {
  const source = `${topic.topic || ''} ${topic.subject || ''} ${keywords.join(' ')} ${topic.explanation || ''}`.toLocaleLowerCase('tr');

  if (textHasAny(source, [/asit/u, /alkaloz/u, /ph\b/u, /hco/u, /paco/u, /pao/u, /anyon/u, /laktat/u, /keton/u])) {
    return 'hangi klinik ve asit-baz paterniyle';
  }
  if (textHasAny(source, [/ekg/u, /qrs/u, /st /u, /t dalgas/u, /aritmi/u, /torsades/u])) {
    return 'hangi EKG ve klinik paternle';
  }
  if (textHasAny(source, [/anti-/u, /ana\b/u, /c3/u, /c4/u, /hbsag/u, /igm/u, /igg/u, /seroloji/u, /kültür/u, /pcr/u, /gram/u, /oksidaz/u, /toksin/u])) {
    return 'hangi laboratuvar veya mikrobiyolojik paternle';
  }
  if (textHasAny(source, [/bt/u, /mr/u, /grafi/u, /ultrason/u, /usg/u, /görüntüleme/u, /dolum defekti/u])) {
    return 'hangi görüntüleme bulgusuyla';
  }
  if (textHasAny(source, [/sinir/u, /duyu/u, /parmak/u, /\bkas\b/u, /el\b/u, /ayak/u, /yürüyüş/u, /ekstansiyon/u, /fleksiyon/u, /fasiyal/u, /abducens/u, /skapula/u, /saphena/u, /malleol/u, /epizyotomi/u, /perineale/u, /perine/u])) {
    return 'hangi anatomik-muayene paterniyle';
  }
  if (textHasAny(source, [/enzim/u, /reseptör/u, /kanal/u, /aquaporin/u, /siklus/u, /amino/u, /glukoz/u, /lipid/u, /vitamin/u, /koenzim/u, /fenilalanin/u, /homosistin/u, /üre/u, /kolesterol/u, /hipoglisemi/u, /hepatomegali/u, /niasin/u, /pellagra/u, /ürat/u])) {
    return 'hangi biyokimyasal paternle';
  }
  if (textHasAny(source, [/tedavi/u, /ilk/u, /yaklaşım/u, /adrenalin/u, /antibiyotik/u, /kalsiyum/u, /insülin/u, /resüsitasyon/u, /profilaksi/u, /aşı/u, /immünizasyon/u])) {
    return 'hangi tedavi veya ilk yaklaşım bilgisiyle';
  }
  if (textHasAny(source, [/gebelik/u, /doğum/u, /fetal/u, /plasenta/u, /membran/u])) {
    return 'hangi obstetrik ipucu paterninde';
  }
  if (textHasAny(source, [/v\/q/u, /perfüzyon/u, /ventilasyon/u, /şant/u, /compliance/u, /kemoreseptör/u, /bpg/u, /oksijen eğrisi/u])) {
    return 'hangi fizyolojik mekanizma paterninde';
  }
  if (textHasAny(source, [/poş/u, /türev/u, /nöral krest/u, /meckel/u, /urakus/u, /pnömosit/u, /hcg/u])) {
    return 'hangi embriyolojik veya histolojik paternle';
  }
  if (textHasAny(source, [/nekroz/u, /karsinom/u, /kanser/u, /metaplazi/u, /psammoma/u, /orphan annie/u, /granülom/u, /podosit/u])) {
    return 'hangi patolojik paternle';
  }
  if (textHasAny(source, [/pnömoni/u, /bakteri/u, /virüs/u, /s\. /u, /c\. /u, /ebv/u, /hsv/u, /hib/u, /legionella/u, /kızamık/u])) {
    return 'hangi enfeksiyöz klinik veya mikrobiyolojik paternle';
  }
  if (textHasAny(source, [/parasetamol/u, /heparin/u, /vankomisin/u, /makrolid/u, /klozapin/u, /lityum/u, /ace inhibitörü/u, /antidot/u, /yan etki/u, /cyp/u])) {
    return 'hangi farmakolojik ipucuyla';
  }
  if (textHasAny(source, [/ateş/u, /ağrı/u, /öksürük/u, /papül/u, /skuam/u, /herald/u, /purpura/u, /sarılık/u, /hipertermi/u, /hipotoni/u, /tremor/u, /bradikinezi/u, /nöbet/u, /kanama/u, /hipertansiyon/u, /hipokalemi/u, /nefrotik/u, /istismar/u, /ekimoz/u, /hemoliz/u, /anemi/u, /coombs/u, /pesi/u, /hemodinamik/u, /atak/u, /oligoklonal/u, /genç kadın/u])) {
    return 'hangi klinik bulgu paterniyle';
  }
  return 'hangi yüksek verimli ipucu zinciriyle';
}

function inferPearlPatternLabel(topic = {}, keywords = []) {
  const source = `${topic.topic || ''} ${topic.explanation || ''} ${keywordItems(keywords).join(' ')}`.toLocaleLowerCase('tr');
  if (textHasAny(source, [/anti-/u, /ana\b/u, /c3/u, /c4/u, /hbsag/u, /igm/u, /igg/u, /seroloji/u, /kültür/u, /pcr/u, /gram/u, /oksidaz/u, /toksin/u, /alp/u, /ggt/u, /bilirübin/u, /trombosit/u, /lenfositoz/u])) return 'laboratuvar veya mikrobiyolojik paternle';
  if (textHasAny(source, [/bt/u, /mr/u, /grafi/u, /ultrason/u, /usg/u, /görüntüleme/u, /sintigrafi/u, /dolum defekti/u])) return 'görüntüleme bulgusuyla';
  if (textHasAny(source, [/sinir/u, /duyu/u, /parmak/u, /kas/u, /el\b/u, /ayak/u, /yürüyüş/u, /ekstansiyon/u, /fleksiyon/u, /fasiyal/u, /abducens/u, /malleol/u, /perine/u])) return 'anatomik veya muayene paterniyle';
  if (textHasAny(source, [/tedavi/u, /ilk/u, /yaklaşım/u, /adrenalin/u, /antibiyotik/u, /kalsiyum/u, /insülin/u, /resüsitasyon/u, /profilaksi/u, /aşı/u, /antidot/u, /pci/u, /fibrinoliz/u, /reperfüzyon/u, /primer perkütan/u])) return 'tedavi önceliğiyle';
  if (textHasAny(source, [/v\/q/u, /perfüzyon/u, /ventilasyon/u, /şant/u, /compliance/u, /kemoreseptör/u, /oksijen/u, /paco₂/u, /paco2/u, /co₂/u, /co2/u, /bos ph/u])) return 'fizyolojik mekanizmayla';
  if (textHasAny(source, [/enzim/u, /reseptör/u, /kanal/u, /aquaporin/u, /taşıyıcı/u, /siklus/u, /amino/u, /glukoz/u, /lipid/u, /vitamin/u, /koenzim/u, /üre/u, /kolesterol/u, /hipoglisemi/u, /hiperürisemi/u])) return 'biyokimyasal mekanizmayla';
  if (textHasAny(source, [/poş/u, /türev/u, /nöral krest/u, /meckel/u, /urakus/u, /pnömosit/u, /hcg/u])) return 'embriyolojik veya histolojik paternle';
  if (textHasAny(source, [/nekroz/u, /karsinom/u, /kanser/u, /metaplazi/u, /psammoma/u, /granülom/u, /podosit/u])) return 'patolojik paternle';
  if (textHasAny(source, [/pnömoni/u, /bakteri/u, /virüs/u, /ebv/u, /hsv/u, /hib/u, /legionella/u, /kızamık/u])) return 'enfeksiyöz klinik paternle';
  if (textHasAny(source, [/parasetamol/u, /heparin/u, /vankomisin/u, /makrolid/u, /klozapin/u, /lityum/u, /ace inhibitörü/u, /yan etki/u, /cyp/u])) return 'farmakolojik ipucuyla';
  return 'anahtar klinik paternle';
}

function buildKeywordFront(topic, keywords = [], topicIndex = 0) {
  const special = SPECIAL_KEYWORD_CARDS[topic.topic];
  if (special?.front) return cleanQuestion(special.front);
  const cues = keywordItems(keywords);
  const compactCues = cues.length >= 3 ? joinTurkishList(cues.slice(0, 3)) : joinTurkishList(cues);

  if (cues.length >= 2) {
    const variants = [
      `${compactCues} paterni en çok hangi kavramı düşündürür`,
      `${compactCues} birlikte görüldüğünde hangi başlık öncelikle düşünülür`,
      `${compactCues} ipuçları hangi cevabı destekler`,
      `Bu ipuçları hangi kavrama yönlendirir: ${compactCues}`,
    ];
    return cleanQuestion(polishGeneratedLead(variants[topicIndex % variants.length]));
  }
  return cleanQuestion(`${cleanText(topic.topic)} için belirleyici ipucu nedir`);
}

const SPECIAL_TRAP_FRONTS = {
  'Salisilat zehirlenmesi': 'Salisilat zehirlenmesi opioid toksidromundan hangi solunum paterniyle ayrılır?',
  'Anafilaksi antihistaminik tuzağı': 'Anafilakside antihistaminik ve steroid neden adrenalinin yerine geçmez?',
  'Hiperkalemi tedavi sırası': 'EKG değişikliği olan hiperkalemide insülin-glukoz neden ilk basamak değildir?',
};

function displayTopicForFront(value = '') {
  return String(value || '').replace(/\s+tuzağı$/iu, '').trim();
}

function polishContrastEntity(value = '') {
  return String(value || '')
    .replace(/\bOpioid toksidrom$/iu, 'Opioid toksidromu')
    .replace(/^Median$/iu, 'Median sinir')
    .replace(/\b([A-ZÇĞİÖŞÜa-zçğıöşü]+) etkisiyle$/u, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripContrastEntity(value = '') {
  const text = String(value || '')
    .replace(/[“”]/g, '')
    .replace(/^[;,.\s]+|[;,.\s]+$/g, '')
    .trim();
  if (!text) return '';

  const comparisonLead = text.match(/^([A-ZÇĞİÖŞÜa-zçğıöşü]+(?:\s+ve\s+[A-ZÇĞİÖŞÜa-zçğıöşü]+)?)(?:\s+[^.;]*?)\b(?:karışır|karışabilir|ile karışır|ile karışabilir)\b/iu);
  if (comparisonLead?.[1]) return polishContrastEntity(comparisonLead[1]);

  const explicitEntityPatterns = [
    /^(.+?\blezyonu)\b/iu,
    /^(.+?\btoksidrom)(?:u|unda|ünde|ında|inde)?\b/iu,
    /^(.+?\bzehirlenmesi)\b/iu,
    /^(.+?\beksikliği)\b/iu,
    /^(.+?\bhastalığı)\b/iu,
    /^(.+?\bsendromu)\b/iu,
    /^(.+?\bkanser)\b/iu,
    /^(.+?\bkarsinom)\b/iu,
    /^(.+?\bsinir)\b/iu,
    /^(.+?\bhormon)\b/iu,
    /^(.+?\benzim)\b/iu,
    /^(.+?\breseptör)\b/iu,
    /^(.+?\bnekrozu)\b/iu,
    /^(.+?\bkalıntısı)\b/iu,
  ];

  for (const pattern of explicitEntityPatterns) {
    const match = text.match(pattern);
    if (match?.[1]) return polishContrastEntity(match[1]);
  }

  const locative = text.match(/^(.{3,90}?)(?:['’]?(?:nda|nde|da|de|ta|te|ında|inde|unda|ünde))\b/iu);
  if (locative?.[1]) return polishContrastEntity(locative[1]);

  const capitalLead = text.match(/^([A-ZÇĞİÖŞÜ][\p{L}0-9.'’+-]+(?:\s+[A-ZÇĞİÖŞÜ][\p{L}0-9.'’+-]+){0,2})\b/u);
  if (capitalLead?.[1] && !/^(Sadece|Bu|Daha)$/u.test(capitalLead[1])) return polishContrastEntity(capitalLead[1]);

  const beforeCue = text.match(/^(.{3,70}?)(?:\s+daha\s+|\s+ise\s+|\s+genellikle\s+|\s+beklenir\b|\s+karışır\b|\s+karışabilir\b)/iu);
  if (beforeCue?.[1]) return polishContrastEntity(beforeCue[1]);

  return '';
}

function inferTrapQuestionDimension(trap = '', topic = {}) {
  const source = `${trap || ''} ${topic.topic || ''}`.toLocaleLowerCase('tr');
  if (textHasAny(source, [/solunum/u, /hiperventilasyon/u, /depresyon/u, /takipne/u, /bronkospazm/u])) return 'solunum paterni';
  if (textHasAny(source, [/asit/u, /alkaloz/u, /ph\b/u, /hco/u, /anyon/u, /laktat/u])) return 'asit-baz paterni';
  if (textHasAny(source, [/ekg/u, /qrs/u, /st /u, /t dalgas/u, /aritmi/u])) return 'EKG veya ritim bulgusu';
  if (textHasAny(source, [/pesi/u, /risk/u, /hemodinamik/u, /şok/u, /mortalite/u])) return 'risk sınıflaması';
  if (textHasAny(source, [/von gierke/u, /mcardle/u, /hipoglisemi/u, /hiperürisemi/u, /laktik asidoz/u, /glikojen/u])) return 'metabolik patern';
  if (textHasAny(source, [/karsinom/u, /kanser/u, /kapsül/u, /damar invazyon/u, /lenfatik/u, /hematolojik yayılım/u])) return 'patolojik yayılım paterni';
  if (textHasAny(source, [/lens/u, /duyu/u, /parmak/u, /ekstansiyon/u, /fleksiyon/u, /yürüyüş/u, /motor/u, /\bkas\b/u, /nörolojik/u, /opozisyon/u, /thenar/u, /ino/u, /oligoklonal/u])) return 'muayene bulgusu';
  if (textHasAny(source, [/tedavi/u, /adrenalin/u, /antihistaminik/u, /steroid/u, /insülin/u, /kalsiyum/u, /vazopressör/u, /antibiyotik/u])) return 'tedavi önceliği';
  if (textHasAny(source, [/şant/u, /perfüzyon/u, /ventilasyon/u, /v\/q/u])) return 'ventilasyon-perfüzyon ilişkisi';
  if (textHasAny(source, [/anti-/u, /ana\b/u, /c3/u, /c4/u, /igg/u, /igm/u, /seroloji/u, /kültür/u, /gram/u, /oksidaz/u, /pcr/u])) return 'laboratuvar paterni';
  if (textHasAny(source, [/bt/u, /mr/u, /grafi/u, /ultrason/u, /usg/u, /görüntüleme/u])) return 'görüntüleme bulgusu';
  if (textHasAny(source, [/enzim/u, /reseptör/u, /kanal/u, /taşıyıcı/u, /siklus/u, /metabolizma/u, /aquaporin/u, /v2/u])) return 'mekanizma bilgisi';
  return 'ayırt ettirici ipucu';
}

function isCompactContrastEntity(value = '') {
  const text = cleanText(value);
  if (!text || text.length > 52) return false;
  if (/[.;:]/u.test(text)) return false;
  if (/(ancak|fakat|çünkü|beklenir|görülür|düşündürür|öncelenir|uyarır)/iu.test(text)) return false;
  return true;
}

function buildTrapFront(topic, topicIndex = 0) {
  if (SPECIAL_TRAP_FRONTS[topic.topic]) return cleanQuestion(SPECIAL_TRAP_FRONTS[topic.topic]);
  const topicName = displayTopicForFront(cleanText(topic.topic));
  const contrast = stripContrastEntity(topic.trap);
  if (isCompactContrastEntity(contrast)) {
    const variants = [
      `${topicName} ile ${contrast} ayrımında kritik fark nedir`,
      `${topicName} ${contrast} ile karıştığında hangi ayrım belirleyicidir`,
      `${topicName} için ${contrast} seçeneğini dışlatan temel nokta nedir`,
    ];
    return cleanQuestion(variants[topicIndex % variants.length]);
  }
  const generic = [
    `${topicName} değerlendirilirken hangi ayırıcı noktaya dikkat edilmelidir`,
    `${topicName} sorusunda yanlış seçeneğe götüren temel karışıklık nedir`,
    `${topicName} için en önemli ayırıcı not nedir`,
  ];
  return cleanQuestion(generic[topicIndex % generic.length]);
}

function stripTusBoilerplate(value = '') {
  return cleanText(value)
    .replace(/^TUS[’']ta\s+/iu, '')
    .replace(/TUS[’']ta\s+/giu, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function buildTusTip(topic, keywords = [], topicIndex = 0) {
  const cues = keywordItems(keywords);
  if (cues.length >= 2) {
    const mainCue = cues[0];
    const support = supportCuePhrase(cues);
    const variants = [
      `Ana ipucu: ${mainCue}; ${support} aynı paterni güçlendirir`,
      `Önce ${mainCue} ipucunu yakala; ${support} ile birlikte düşün`,
      `${polishGeneratedLead(mainCue)} yön verir; ${support} tabloyu tamamlar`,
      `Bu kartta belirleyici ipucu ${mainCue}; ${support} ayrımı netleştirir`,
    ];
    return cleanSentence(polishGeneratedLead(variants[topicIndex % variants.length]));
  }
  if (cues.length === 1) return cleanSentence(polishGeneratedLead(`${cues[0]} bu kartın belirleyici ipucudur`));
  return cleanSentence(stripTusBoilerplate(topic.explanation));
}

function buildVariantExplanation(topic, variant, keywords = []) {
  const explanation = cleanSentence(stripTusBoilerplate(topic.explanation));
  const trap = cleanSentence(stripTusBoilerplate(topic.trap));
  const special = SPECIAL_KEYWORD_CARDS[topic.topic];

  if (variant === 'keywords') {
    if (special?.explanation) return cleanSentence(stripTusBoilerplate(special.explanation));
    return explanation;
  }
  if (variant === 'trap') {
    return explanation;
  }
  if (variant === 'extra') {
    return explanation;
  }
  return explanation;
}

function buildCard(topic, topicIndex, variantIndex) {
  const keywords = compactList(topic.keywords);
  const variant = VARIANT_LABELS[variantIndex];
  const base = {
    id: `tus-pearl-${topic.branchId}-${String(topicIndex + 1).padStart(3, '0')}-${variant}`,
    branchId: topic.branchId,
    subject: cleanText(topic.subject),
    topic: cleanText(topic.topic),
    keywords: keywords.map((keyword) => cleanText(keyword)).filter(Boolean),
    appearedYears: [],
    appearanceCount: 0,
    difficulty: topic.difficulty || 'orta',
    sourceType: 'KlinikIQ yüksek verim TUS çekirdek kartı',
    isHighYield: true,
    isPastQuestionDerived: false,
  };

  if (variant === 'spot') {
    return {
      ...base,
      front: cleanQuestion(topic.mainQuestion),
      back: cleanSentence(topic.mainAnswer),
      answer: cleanSentence(topic.mainAnswer),
      explanation: buildVariantExplanation(topic, variant, keywords),
      tusTip: buildTusTip(topic, keywords, topicIndex),
      differentialNote: cleanSentence(topic.trap),
      cardType: 'Aktif hatırlama',
    };
  }
  if (variant === 'keywords') {
    const special = SPECIAL_KEYWORD_CARDS[topic.topic] || {};
    const answer = special.answer || buildKeywordBack(topic, keywords, topicIndex);
    return {
      ...base,
      front: buildKeywordFront(topic, keywords, topicIndex),
      back: cleanSentence(answer),
      answer: cleanSentence(answer),
      explanation: buildVariantExplanation(topic, variant, keywords),
      tusTip: special.tusTip ? cleanSentence(stripTusBoilerplate(special.tusTip)) : '',
      differentialNote: special.differentialNote ? cleanSentence(special.differentialNote) : cleanSentence(topic.trap),
      cardType: 'Anahtar patern',
    };
  }
  if (variant === 'trap') {
    const answer = cleanSentence(topic.trap);
    return {
      ...base,
      front: buildTrapFront(topic, topicIndex),
      back: cleanSentence(answer),
      answer: cleanSentence(answer),
      explanation: buildVariantExplanation(topic, variant, keywords),
      tusTip: '',
      differentialNote: '',
      cardType: 'Ayırıcı nokta',
    };
  }
  return {
    ...base,
    front: cleanQuestion(topic.extraQuestion),
    back: cleanSentence(topic.extraAnswer),
    answer: cleanSentence(topic.extraAnswer),
    explanation: buildVariantExplanation(topic, variant, keywords),
    tusTip: '',
    differentialNote: cleanSentence(topic.trap),
    cardType: 'Kısa uygulama',
  };
}

export function buildTusPearlCards() {
  return TUS_PEARL_TOPICS.flatMap((topic, topicIndex) => VARIANT_LABELS.map((_, variantIndex) => buildCard(topic, topicIndex, variantIndex)));
}

export const TUS_PEARL_CARDS = buildTusPearlCards();

export const TUS_PEARL_CARD_STATS = Object.freeze({
  total: TUS_PEARL_CARDS.length,
  pastQuestionCount: TUS_PEARL_CARDS.filter((card) => card.appearedYears?.length || card.isPastQuestionDerived).length,
  byBranch: TUS_PEARL_CARDS.reduce((acc, card) => {
    acc[card.branchId] = (acc[card.branchId] || 0) + 1;
    return acc;
  }, {}),
});

function normalizeOption(value = '') {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeOptionKey(value = '') {
  return normalizeOption(value)
    .toLocaleLowerCase('tr')
    .replace(/intravenöz|intravenoz/giu, 'iv')
    .replace(/(^|\s)[ıi]v(?=\s|$)/giu, '$1iv')
    .replace(/adrenalin|epinefrin/giu, 'adrenalin')
    .replace(/insülin|insulin/giu, 'insulin')
    .replace(/glukoz|dekstroz|glucose/giu, 'glukoz')
    .replace(/k\+|k⁺/giu, 'potasyum')
    .replace(/[.;:!?()]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function uniqueOptionsBySemanticKey(items = [], forbiddenKey = '') {
  const seen = new Set([forbiddenKey].filter(Boolean));
  const out = [];
  items.forEach((item) => {
    const text = normalizeOption(item);
    const key = normalizeOptionKey(text);
    if (!text || !key || seen.has(key)) return;
    seen.add(key);
    out.push(text);
  });
  return out;
}

function buildDistractors(card, index) {
  const correctKey = normalizeOptionKey(card.back);
  const sameBranch = TUS_PEARL_CARDS
    .filter((item) => item.branchId === card.branchId && item.id !== card.id)
    .map((item) => normalizeOption(item.back));
  const global = TUS_PEARL_CARDS
    .filter((item) => item.branchId !== card.branchId)
    .map((item) => normalizeOption(item.back));
  const pool = uniqueOptionsBySemanticKey([...sameBranch, ...global], correctKey);
  if (!pool.length) return ['Yakın ama eksik seçenek', 'Farklı mekanizma', 'Geç dönem komplikasyon', 'Destekleyici bulgu'];
  const start = (index * 7) % pool.length;
  const rotated = [...pool.slice(start), ...pool.slice(0, start)];
  return uniqueOptionsBySemanticKey(rotated, correctKey).slice(0, 4);
}

export const TUS_PEARL_AI_SEEDS = TUS_PEARL_CARDS.slice(0, 220).map((card, index) => {
  const distractors = buildDistractors(card, index);
  const optionTexts = [normalizeOption(card.back), ...distractors].filter(Boolean).slice(0, 5);
  return {
    seedId: `ai-pearl-seed-${card.id}`,
    source: 'tus-pearl-card-seed',
    title: card.topic,
    relatedBranch: card.subject,
    branchId: 'tus-spot-olgular',
    originalBranchId: card.branchId,
    spotCategory: `AI Spot • ${card.subject}`,
    difficulty: card.difficulty || 'orta',
    learningTarget: card.front,
    correctConcept: normalizeOption(card.back),
    demographics: null,
    setting: null,
    chiefComplaint: card.topic,
    stem: null,
    exam: [],
    vitals: {},
    investigations: [],
    question: null,
    questionType: 'spot',
    options: optionTexts.map((text, optionIndex) => ({ id: ['A', 'B', 'C', 'D', 'E'][optionIndex], text })),
    correctAnswer: 'A',
    explanation: card.explanation,
    wrongOptionFeedback: {},
    evidenceChain: [card.explanation, ...card.keywords].filter(Boolean).slice(0, 4),
    evidenceConcepts: [card.explanation, ...card.keywords].filter(Boolean).slice(0, 4),
    examPearl: card.back,
    managementSteps: [],
    sourceCardId: card.id,
  };
});
